import hashlib
import hmac
import os
import time
from typing import Optional

from flask import Flask, abort, request

TOLERANCE_SECONDS = 300

def verify_strait_signature(secret: str, raw_body: bytes, header: Optional[str]) -> bool:
    if not header:
        return False
    parts = dict(p.strip().split("=", 1) for p in header.split(",") if "=" in p)
    t, v1 = parts.get("t", ""), parts.get("v1", "")
    if not t.isdigit() or not v1:
        return False
    if abs(time.time() - int(t)) > TOLERANCE_SECONDS:
        return False
    expected = hmac.new(secret.encode(), t.encode() + b"." + raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, v1)

app = Flask(__name__)

@app.post("/webhooks/links")
def strait_webhook():
    raw = request.get_data()  # the exact bytes we sent
    if not verify_strait_signature(os.environ["WEBHOOK_SECRET"], raw, request.headers.get("X-Strait-Signature")):
        abort(401)
    event = request.get_json()
    # handle event["event"] / event["data"] …
    return "", 204
